var legadoJava = null;
var runtimeConfig = null;
var CONFIG_APP_URL = 'https://umeng-log-v5.gz.bcebos.com/cloud/app/com.funny.syzs/appService.json';
var CONFIG_UPDATE_URL = 'https://umeng-log-v5.gz.bcebos.com/cloud/app/com.funny.syzs/update.json';
var CONFIG_CACHE_MS = 21600000;

function bindEnv(javaHelper) {
    legadoJava = javaHelper;
}

function getLegadoJava() {
    if (!legadoJava) {
        throw new Error('jsLib java 未绑定');
    }
    return legadoJava;
}

function parseJson(text, fallback) {
    try {
        return JSON.parse(String(text || ''));
    } catch (e) {
        return fallback;
    }
}

function cleanText(text) {
    return String(text == null ? '' : text)
        .replace(/<br\s*\/?>/ig, '\n')
        .replace(/<\/p>/ig, '\n')
        .replace(/<[^>]+>/g, '')
        .replace(/&nbsp;/ig, ' ')
        .replace(/\r\n/g, '\n')
        .replace(/\r/g, '\n')
        .trim();
}

function cleanTitle(text) {
    return cleanText(text).replace(/<\/?word>/ig, '');
}

function formatIntro(text) {
    var cleaned = cleanText(text);
    if (!cleaned) {
        return '';
    }
    var parts = cleaned.split(/\n+/).map(function(part) {
        return part.replace(/\s+/g, ' ').trim();
    }).filter(function(part) {
        return !!part;
    });
    return parts.join('\n\n');
}

function pushUnique(list, value) {
    if (value && list.indexOf(value) === -1) {
        list.push(value);
    }
}

function createApiHeaders() {
    var java = getLegadoJava();
    var time = String(new Date().getTime());
    return {
        'Content-Type': 'application/json',
        'User-Agent': 'okhttp/4.11.0',
        appId: 'com.funny.syzs',
        appVersion: '1',
        time: time,
        sign: java.md5Encode('qwer' + time + 'com.funny.syzs' + '1' + 'rewq')
    };
}

function decodeEncData(encData) {
    var java = getLegadoJava();
    var bytes = java.base64DecodeToByteArray(encData);
    return java.createSymmetricCrypto('DES/ECB/PKCS5Padding', 'rThYzbEp').decryptStr(bytes);
}

function unwrapPayload(rawText) {
    var body = parseJson(rawText, null);
    if (!body) {
        return null;
    }
    if (body.code === 1001 && body.body && body.body.encData) {
        return parseJson(decodeEncData(body.body.encData), null);
    }
    return body;
}

function getSourceCtx() {
    try {
        if (typeof source !== 'undefined' && source) {
            return source;
        }
    } catch (e) {}
    return null;
}

function readConfigCache() {
    var src = getSourceCtx();
    if (!src || !src.getLoginInfo) {
        return runtimeConfig;
    }
    var cache = parseJson(src.getLoginInfo(), null);
    return cache && cache.appService ? cache : runtimeConfig;
}

function writeConfigCache(appService, update) {
    runtimeConfig = {
        appService: appService || {},
        update: update || {},
        ts: new Date().getTime()
    };
    var src = getSourceCtx();
    if (src && src.putLoginInfo) {
        try {
            src.putLoginInfo(JSON.stringify(runtimeConfig));
        } catch (e) {}
    }
    return runtimeConfig;
}

function requestResponse(url, method, body) {
    var java = getLegadoJava();
    var headers = createApiHeaders();
    if ((method || 'GET').toUpperCase() === 'POST') {
        return java.post(url, JSON.stringify(body || {}), headers);
    }
    return java.get(url, headers);
}

function getResponseStatus(res) {
    try {
        if (res && res.code) {
            return Number(res.code());
        }
        if (res && res.statusCode) {
            return Number(res.statusCode());
        }
        return 0;
    } catch (e) {
        return 0;
    }
}

function getResponseBody(res) {
    try {
        return res && res.body ? String(res.body() || '') : '';
    } catch (e) {
        return '';
    }
}

function requestJson(url, method, body) {
    return unwrapPayload(getResponseBody(requestResponse(url, method, body)));
}

function ensureConfig(forceRefresh) {
    var now = new Date().getTime();
    if (!forceRefresh && runtimeConfig && runtimeConfig.appService && runtimeConfig.ts && now - Number(runtimeConfig.ts) < CONFIG_CACHE_MS) {
        return runtimeConfig;
    }
    var cache = readConfigCache();
    if (!forceRefresh && cache && cache.appService && cache.ts && now - Number(cache.ts) < CONFIG_CACHE_MS) {
        runtimeConfig = cache;
        return runtimeConfig;
    }
    var appService = requestJson(CONFIG_APP_URL, 'GET');
    var update = requestJson(CONFIG_UPDATE_URL, 'GET') || (cache ? cache.update : {});
    if (!appService && cache && cache.appService) {
        runtimeConfig = cache;
        return runtimeConfig;
    }
    if (!appService) {
        if (cache && cache.appService) {
            runtimeConfig = cache;
            return runtimeConfig;
        }
        throw new Error('轻云配置获取失败，且无可用缓存');
    }
    return writeConfigCache(appService, update);
}

function joinUrl(base, path) {
    var left = String(base || '');
    var right = String(path || '');
    if (!left) {
        return right;
    }
    if (!right) {
        return left;
    }
    if (/^https?:\/\//i.test(right)) {
        return right;
    }
    if (left.charAt(left.length - 1) === '/' && right.charAt(0) === '/') {
        return left + right.substring(1);
    }
    if (left.charAt(left.length - 1) !== '/' && right.charAt(0) !== '/') {
        return left + '/' + right;
    }
    return left + right;
}

function getBusinessBase(mode) {
    var cfg = ensureConfig().appService || {};
    if (mode === 'list') {
        return cfg.businessDynamicAddress || cfg.businessStaticAddress || '';
    }
    return cfg.businessStaticAddress || cfg.businessDynamicAddress || '';
}

function stripRequestUrl(url) {
    var text = String(url || '');
    var idx = text.indexOf(',{');
    if (idx > -1) {
        return text.substring(0, idx);
    }
    return text;
}

function extractApiPath(url) {
    var text = stripRequestUrl(url);
    var idx = text.indexOf('/api/');
    return idx > -1 ? text.substring(idx) : text;
}

function hasUsablePayload(data) {
    if (!data) {
        return false;
    }
    if (Array.isArray(data)) {
        return data.length > 0;
    }
    if (Array.isArray(data.items)) {
        return data.items.length > 0;
    }
    if (Array.isArray(data.list)) {
        return data.list.length > 0;
    }
    return true;
}

function requestBusinessData(pathOrUrl, method, body) {
    var rawUrl = stripRequestUrl(pathOrUrl);
    var path = extractApiPath(rawUrl);
    var cfg = ensureConfig().appService || {};
    var candidates = [];
    function pushUrl(url) {
        if (url && candidates.indexOf(url) === -1) {
            candidates.push(url);
        }
    }
    if (/^https?:\/\//i.test(rawUrl)) {
        pushUrl(rawUrl);
    }
    if (path) {
        pushUrl(joinUrl(cfg.businessStaticAddress || '', path));
        pushUrl(joinUrl(cfg.businessDynamicAddress || '', path));
    }
    if (!candidates.length && rawUrl) {
        pushUrl(rawUrl);
    }
    var lastData = null;
    for (var i = 0; i < candidates.length; i += 1) {
        try {
            var res = requestResponse(candidates[i], method, body);
            var data = unwrapPayload(getResponseBody(res));
            var status = getResponseStatus(res);
            if (data != null) {
                lastData = data;
            }
            if (status === 404) {
                continue;
            }
            if (hasUsablePayload(data)) {
                return data;
            }
        } catch (e) {}
    }
    return lastData;
}

function createRequest(url, method, body) {
    var options = {
        method: method || 'GET',
        headers: createApiHeaders()
    };
    if (body != null) {
        options.body = body;
    }
    return url + ',' + JSON.stringify(options);
}

function buildBusinessRequest(path, mode, method, body) {
    return createRequest(joinUrl(getBusinessBase(mode), path), method || 'GET', body);
}

function buildSearchRequest(keyword, pageNo) {
    var cfg = ensureConfig().appService || {};
    return createRequest(joinUrl(cfg.searchAddress || '', '/api/search/v1/albums'), 'POST', {
        key: keyword,
        page: pageNo
    });
}

