function normalizeExplorePayload(data) {
    if (Array.isArray(data)) {
        var list = [];
        for (var i = 0; i < data.length; i += 1) {
            var group = data[i] || {};
            var albums = Array.isArray(group.albums) ? group.albums : [];
            for (var j = 0; j < albums.length; j += 1) {
                var src = albums[j] || {};
                var item = {};
                for (var key in src) {
                    item[key] = src[key];
                }
                if (group.groupName) {
                    item._qyGroupName = group.groupName;
                }
                list.push(item);
            }
        }
        return list;
    }
    if (data && Array.isArray(data.items)) {
        return data.items;
    }
    return [];
}

function getAnnouncerText(item) {
    if (!item) {
        return '';
    }
    if (typeof item.announcerName === 'string' && item.announcerName) {
        return cleanText(item.announcerName);
    }
    if (typeof item.announcers === 'string' && item.announcers) {
        return cleanText(item.announcers);
    }
    if (Array.isArray(item.announcers)) {
        var names = [];
        for (var i = 0; i < item.announcers.length; i += 1) {
            var cur = item.announcers[i] || {};
            pushUnique(names, cleanText(cur.announcerName || cur.name || cur.title || ''));
        }
        return names.join(' / ');
    }
    return '';
}

function appendTagValues(list, value) {
    if (!value) {
        return;
    }
    if (Array.isArray(value)) {
        for (var i = 0; i < value.length; i += 1) {
            appendTagValues(list, value[i]);
        }
        return;
    }
    if (typeof value === 'object') {
        pushUnique(list, cleanText(value.tagName || value.name || value.title || value.categoryName || value.label || ''));
        return;
    }
    pushUnique(list, cleanText(value));
}

function getTagsText(item) {
    var tags = [];
    if (!item) {
        return '';
    }
    appendTagValues(tags, item._qyGroupName);
    appendTagValues(tags, item.tag);
    appendTagValues(tags, item.categories);
    appendTagValues(tags, item.tags);
    return tags.join(' / ');
}

function getCoverUrl(item) {
    var cfg = ensureConfig().appService || {};
    return joinUrl(cfg.staticResource || '', item && item.coverPath ? item.coverPath : '');
}

function normalizeAlbumItem(item) {
    return {
        bookId: String((item && (item.id || item.albumId)) || ''),
        title: cleanTitle(item && (item.title || item.name || '')),
        authorText: getAnnouncerText(item),
        kindText: getTagsText(item),
        introText: formatIntro(item && (item.desc || item.description || '')),
        coverUrl: getCoverUrl(item)
    };
}

function mapAlbumItems(list) {
    if (!Array.isArray(list)) {
        return [];
    }
    return list.map(function(item) {
        return JSON.stringify(normalizeAlbumItem(item));
    });
}

function normalizeBookInfo(item) {
    var authorParts = [];
    var authorName = cleanText(item && item.author ? item.author : '');
    var announcerName = getAnnouncerText(item);
    if (authorName) {
        pushUnique(authorParts, authorName);
    }
    if (announcerName) {
        pushUnique(authorParts, '演播：' + announcerName);
    }
    var kindParts = [];
    var tagsText = getTagsText(item);
    var trackCount = item && (item.trackCount || item.chapterCount || item.count);
    if (tagsText) {
        kindParts.push(tagsText);
    }
    if (trackCount) {
        kindParts.push('共' + trackCount + '集');
    }
    return {
        bookId: String((item && item.id) || ''),
        title: cleanTitle(item && item.title ? item.title : ''),
        authorText: authorParts.join(' / '),
        kindText: kindParts.join(' / '),
        introText: formatIntro(item && item.desc ? item.desc : '')
    };
}

function extractAlbumIdFromUrl(url) {
    var rawUrl = stripRequestUrl(url);
    var match = rawUrl.match(/\/album\/(?:tracks|info|analysis)\/([^\/?]+)(?:\/[^\/?]+)?\.json/i);
    return match ? match[1] : '';
}

function getTrackItems(data) {
    if (Array.isArray(data)) {
        return data;
    }
    if (data && Array.isArray(data.items)) {
        return data.items;
    }
    if (data && Array.isArray(data.list)) {
        return data.list;
    }
    return [];
}

function mapChapterItems(list, fallbackAlbumId) {
    if (!Array.isArray(list)) {
        return [];
    }
    return list.map(function(item) {
        return JSON.stringify({
            chapterId: String((item && item.id) || ''),
            albumId: String((item && item.albumId) || fallbackAlbumId || ''),
            chapterName: cleanTitle(item && (item.title || item.name || ''))
        });
    });
}

function getResultPayload(rawText) {
    return unwrapPayload(rawText);
}

function buildLanrenPlayContent(data) {
    var java = getLegadoJava();
    var extras = data && data.extras ? data.extras : {};
    var sourceExtras = data && data.sourceExtras ? data.sourceExtras : {};
    var freeProviderSetting = parseJson(extras.freeProviderSetting, {});
    if (!extras.apiUrl || !freeProviderSetting) {
        return '';
    }
    var t13 = String(new Date().getTime());
    var path = '/yyting/v2/gateway/getListenPath?costInfo=&duId=' + (freeProviderSetting.duid || '') + '&entityId=' + (data.sourceAlbumId || '') + '&entityType=' + (sourceExtras.entityType || '') + '&id=' + (data.sourceTrackId || '') + '&imei=' + (freeProviderSetting.imei || '') + '&lrid=' + (freeProviderSetting.lrid || '') + '&mode=0&nwt=1&opType=' + (freeProviderSetting.opType || '') + '&ostar36=' + (freeProviderSetting.ostar36 || '') + '&removeBgs=0&section=' + (sourceExtras.section || '') + '&token=' + (freeProviderSetting.token || '') + '&ts=' + t13 + '&userMode=' + (freeProviderSetting.userMode || '');
    var playUrl = String(extras.apiUrl) + path + '&sc=' + java.md5Encode(path + 'vYCmm+6CFVykQk5w0wiUDliCQRA=');
    var headers = {
        'User-Agent': String(freeProviderSetting.ua || 'okhttp/4.11.0')
    };
    for (var i = 0; i < 3; i += 1) {
        try {
            var res = parseJson(java.get(playUrl, headers).body(), null);
            if (res && res.apiStatus === 0 && res.data && res.data.path) {
                return String(res.data.path);
            }
        } catch (e) {}
    }
    return '';
}


function hasPlayData(obj) {
    if (!obj) {
        return false;
    }
    return !!(
        obj.accessPath || obj.playType || obj.path || obj.url || obj.playUrl || obj.audioUrl || obj.mediaUrl || obj.fileUrl ||
        (obj.data && (obj.data.accessPath || obj.data.playType || obj.data.path || obj.data.url || obj.data.playUrl || obj.data.audioUrl || obj.data.mediaUrl || obj.data.fileUrl)) ||
        (obj.list && obj.list.length) || obj.extras || (obj.data && obj.data.extras)
    );
}

function normalizePlayData(obj) {
    if (obj && obj.data && !obj.accessPath && !obj.playType && !obj.extras && !obj.sourceTrackId && !obj.sourceAlbumId && hasPlayData(obj.data)) {
        return obj.data;
    }
    return obj;
}

function appendMusicFlag(url) {
    var text = String(url || '');
    if (!text) {
        return '';
    }
    if (text.indexOf('#isMusic=true#') > -1) {
        return text;
    }
    var optionIndex = text.indexOf(',{');
    if (optionIndex > -1) {
        return text.substring(0, optionIndex) + '#isMusic=true#' + text.substring(optionIndex);
    }
    return text + '#isMusic=true#';
}

function pickDirectUrl(obj) {
    function push(list, value) {
        var text = String(value || '');
        if (!text || list.indexOf(text) > -1) {
            return;
        }
        if (text.indexOf('http://') === 0 || text.indexOf('https://') === 0 || text.indexOf('//') === 0) {
            list.push(text);
        }
    }
    function collect(list, target) {
        if (!target) {
            return;
        }
        push(list, target.path);
        push(list, target.url);
        push(list, target.playUrl);
        push(list, target.audioUrl);
        push(list, target.mediaUrl);
        push(list, target.fileUrl);
        if (Array.isArray(target.list) && target.list.length) {
            collect(list, target.list[0]);
        }
    }
    var urls = [];
    collect(urls, obj);
    if (obj && obj.data) {
        collect(urls, obj.data);
    }
    if (!urls.length) {
        return '';
    }
    var directUrl = urls[0];
    if (directUrl.indexOf('//') === 0) {
        directUrl = 'http:' + directUrl;
    }
    return appendMusicFlag(directUrl);
}

function buildSelfPlayUrl(path) {
    var cfg = ensureConfig();
    var appService = cfg.appService || {};
    var update = cfg.update || {};
    var j = getLegadoJava();
    var mediaPath = String(path || '');
    if (!mediaPath) {
        return '';
    }
    var t13 = String(new Date().getTime());
    var t11 = t13.substring(0, 11);
    var sign1 = '$$' + j.md5Encode(j.md5Encode('bOLpce2OsGWj7cJu6VXEscK7QyXawZzg' + mediaPath)) + '$$';
    var sign2 = '$$' + j.md5Encode(j.md5Encode('i*Tc^pJ~Wp^.sCNtkhIMZcF*275o4Pvk' + mediaPath)) + '$$';
    var headers = {
        'Icy-MetaData': '1',
        'Accept-Encoding': 'identity',
        'User-Agent': 'okhttp/4.11.0',
        initStatus: 'true',
        version: String(update.latestVersionName || '1.0.4'),
        versionCode: String(update.latestVersionCode || '3'),
        psign: '9f05e35446d7d6d886ecafdf7d689db2',
        userId: 'b012b709e395a2da6d5774fc586cf842',
        clientTime: t11 + '99',
        appChannel: 'normal',
        rewardTime: '0',
        freeTime: t13,
        appKey: 'com.funny.syzs',
        sTime: t13,
        sign1: sign1,
        sign2: sign2,
        sign3: '99' + '35288721' + t11
    };
    return joinUrl(appService.trackResource || 'http://track.umeng-mlog.com/', mediaPath) + '#isMusic=true#,' + JSON.stringify({ headers: headers });
}

