ruleContent.content:
@js:
bindEnv(java);
var data = normalizePlayData(getResultPayload(result));
if (!hasPlayData(data) && baseUrl) {
    data = normalizePlayData(requestBusinessData(baseUrl, 'GET')) || data;
}
if (!hasPlayData(data) && baseUrl) {
    try {
        data = normalizePlayData(getResultPayload(java.ajax(baseUrl))) || data;
    } catch (e) {}
}
if (!hasPlayData(data)) {
    result = '';
} else {
    var javaHelper = getLegadoJava();
    var accessPath = String((data && data.accessPath) || '');
    var playType = String((data && data.playType) || '').toLowerCase();
    var extras = data && data.extras ? data.extras : {};
    var sourceExtras = data && data.sourceExtras ? data.sourceExtras : {};
    var freeProviderSetting = parseJson(extras.freeProviderSetting, {});
    result = pickDirectUrl(data);
    if (!result && accessPath && playType === 'self') {
        result = buildSelfPlayUrl(accessPath);
    }
    if (!result && extras.apiUrl2) {
        var api2Headers = {
            'User-Agent': String(freeProviderSetting.ua || 'okhttp/4.11.0'),
            Connection: 'keep-alive',
            Accept: '*/*'
        };
        if (extras.cookie) {
            api2Headers.cookie = javaHelper.base64Decode(extras.cookie);
        }
        try {
            var params = '/ajax/getPlayPath?entityId=' + (data.sourceAlbumId || '') + '&entityType=3&opType=1&sections=%5B' + (sourceExtras.section || '') + '%5D&type=0&section=' + (sourceExtras.section || '') + '&id=' + (data.sourceTrackId || '');
            var res2 = parseJson(javaHelper.get(String(extras.apiUrl2) + params, api2Headers).body(), {});
            result = pickDirectUrl(res2);
        } catch (e) {}
    }
    if (!result && playType === 'lanren') {
        result = buildLanrenPlayContent(data);
        if (result) {
            result = appendMusicFlag(result);
        }
    }
    if (!result && accessPath) {
        result = buildSelfPlayUrl(accessPath);
    }
    if (!result) {
        result = pickDirectUrl(data);
    }
}
result;

