@js:
bindEnv(java);
var albumId = extractAlbumIdFromUrl(baseUrl);
var data = getResultPayload(result);
var tracks = getTrackItems(data);
if (!tracks.length && baseUrl) {
    data = requestBusinessData(baseUrl, 'GET');
    tracks = getTrackItems(data);
}
if (!tracks.length && albumId) {
    data = requestBusinessData('/api/business/v1/album/tracks/' + albumId + '.json', 'GET');
    tracks = getTrackItems(data);
}
result = mapChapterItems(tracks, albumId);
result;

ruleToc.chapterUrl:
@js:
bindEnv(java);
var item = parseJson(result, {});
var albumId = String((item && item.albumId) || extractAlbumIdFromUrl(baseUrl) || '');
var chapterId = String((item && item.chapterId) || '');
var req = String(baseUrl || '');
var commaIndex = req.indexOf(',');
if (commaIndex > -1) {
    req = req.substring(0, commaIndex).replace(/\/api\/business\/v1\/album\/(?:tracks|analysis)\/[^\/?,]+(?:\/[^\/?,]+)?\.json/i, '/api/business/v1/album/analysis/' + albumId + '/' + chapterId + '.json') + req.substring(commaIndex);
    result = req;
} else {
    result = buildBusinessRequest('/api/business/v1/album/analysis/' + albumId + '/' + chapterId + '.json', 'info');
}
result;
